$responses$::jsonb;
  item jsonb;
  response_id uuid;
  inserted_count integer := 0;
  affected_count integer;
begin
  if target_slug is null or btrim(target_slug) = '' then
    select count(*), min(slug), string_agg(format('%s (slug: %s)', training_title, slug), '; ' order by slug)
    into form_count, target_slug, available_forms
    from public.feedback_forms
    where form_type = 'csf';

    if form_count = 0 then
      raise exception 'No CSF form exists. Create a Customer Satisfaction form in the app (Forms page) first, then rerun.';
    elsif form_count > 1 then
      raise exception 'Several CSF forms exist. Set target_slug at the top to one of: %', available_forms;
    end if;
  end if;

  select id into target_id from public.feedback_forms where slug = target_slug and form_type = 'csf';
  if target_id is null then
    raise exception 'CSF form "%" not found.', target_slug;
  end if;

  if jsonb_array_length(payload) <> 84 then
    raise exception 'Expected exactly 84 responses.';
  end if;

  for item in select value from jsonb_array_elements(payload)
  loop
    response_id := md5(target_id::text || ':' || (item #>> '{_paperImport,sourceFile}') || ':' || (item #>> '{_paperImport,page}'))::uuid;
    insert into public.csf_responses (id, feedback_form_id, response)
    values (response_id, target_id, item)
    on conflict (id) do nothing;
    get diagnostics affected_count = row_count;
    inserted_count := inserted_count + affected_count;
  end loop;

  raise notice 'Inserted %, already present %.', inserted_count, 84 - inserted_count;
end;
$import$;

-- Check (expect 38 and 46):
select f.slug, r.response #>> '{_paperImport,sourceFile}' as source_pdf, count(*) as imported
from public.csf_responses r
join public.feedback_forms f on f.id = r.feedback_form_id
where r.response #>> '{_paperImport,batch}' = 'csf-scans-013198-013152'
group by f.slug, source_pdf
order by source_pdf;
